const fs=require('fs'); const {spawn}=require('child_process'); const {createRequire}=require('module'); const req=createRequire('/Users/dq/Documents/ERP/hub-erp-v0/server/package.json'); const sql=req('mssql'), bcrypt=req('bcryptjs');
const ROOT='/Users/dq/Documents/ERP/hub-erp-v0', API='http://127.0.0.1:3002/api', FRONT='http://127.0.0.1:8099'; const ev={runTag:`P1FEFIX2-${Date.now()}`,checks:[],defects:[]};
function env(){let o={}; for(const l of fs.readFileSync(ROOT+'/server/.env','utf8').split(/\r?\n/)){const m=l.match(/^([^#=]+)=(.*)$/); if(m)o[m[1].trim()]=m[2].trim()} return o} function sleep(ms){return new Promise(r=>setTimeout(r,ms))} function add(id,ok,d){const it={id,status:ok?'PASS':'FAIL',detail:d}; ev.checks.push(it); if(!ok)ev.defects.push(it); console.log(`${ok?'✅':'❌'} ${id}`)}
async function api(p,opt={}){const r=await fetch(API+p,{...opt,headers:{'content-type':'application/json',...(opt.headers||{})}}); const t=await r.text(); let j; try{j=JSON.parse(t)}catch{j=t} if(!r.ok)throw new Error(j?.message||t); return j.data||j}
class C{constructor(ws){this.wsUrl=ws;this.id=0;this.p=new Map()} async connect(){this.ws=new WebSocket(this.wsUrl); await new Promise((res,rej)=>{this.ws.onopen=res;this.ws.onerror=rej}); this.ws.onmessage=e=>{const m=JSON.parse(e.data); if(m.id&&this.p.has(m.id)){const x=this.p.get(m.id);this.p.delete(m.id);m.error?x.reject(new Error(m.error.message)):x.resolve(m.result)}}} send(method,params={}){const id=++this.id;this.ws.send(JSON.stringify({id,method,params}));return new Promise((resolve,reject)=>{this.p.set(id,{resolve,reject});setTimeout(()=>reject(new Error('timeout '+method)),10000)})} async eval(expression){const r=await this.send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true});return r.result.value}}
(async()=>{const e=env(); const pool=await sql.connect({server:e.DB_MSSQL_HOST||'localhost',port:+(e.DB_MSSQL_PORT||1433),user:e.DB_MSSQL_USERNAME,password:e.DB_MSSQL_PASSWORD,database:e.DB_MSSQL_DATABASE,options:{encrypt:false,trustServerCertificate:true}}); const u='p1fe2_'+Date.now(); const pw='P1fe_pwd'; await pool.request().input('u',u).input('p',bcrypt.hashSync(pw,10)).query("insert into sys_user (username,password,real_name,status,created_at,updated_at,is_deleted) values (@u,@p,'P1FE',1,getdate(),getdate(),0)"); await pool.close(); const login=await api('/auth/login',{method:'POST',body:JSON.stringify({username:u,password:pw})});
const port=9800+Math.floor(Math.random()*300); const proc=spawn('/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--remote-debugging-port='+port,'--user-data-dir=/tmp/'+ev.runTag,'about:blank'],{stdio:'ignore'}); for(let i=0;i<50;i++){try{if((await fetch('http://127.0.0.1:'+port+'/json/version')).ok)break}catch{} await sleep(100)} const target=await (await fetch('http://127.0.0.1:'+port+'/json/new?about:blank',{method:'PUT'})).json(); const c=new C(target.webSocketDebuggerUrl); await c.connect(); await c.send('Page.enable'); await c.send('Runtime.enable');
const preload=`Object.defineProperty(window,'PURCHASE_API_BASE',{value:'${API}',configurable:true});Object.defineProperty(window,'PURCHASE_P0_API_BASE',{value:'${API}',configurable:true});window.__p1Fetch=[];try{localStorage.setItem('accessToken','${login.accessToken}')}catch(e){};const __oldFetch=window.fetch.bind(window);window.fetch=function(){window.__p1Fetch.push(String(arguments[0]));return __oldFetch.apply(window,arguments);};`;
await c.send('Page.addScriptToEvaluateOnNewDocument',{source:preload});
for(const p of ['purchase-return-request.html','purchase-return-request-create.html','purchase-return.html','purchase-return-create.html']){await c.send('Page.navigate',{url:`${FRONT}/pages/${p}`}); await sleep(1800); const info=await c.eval(`(()=>({base:window.PURCHASE_API_BASE,banner:!!document.getElementById('p1ReturnBanner'),fetches:(window.__p1Fetch||[]).concat(performance.getEntriesByType('resource').map(e=>e.name)),text:document.body.innerText.slice(0,800)}))()`); const ok=info.banner && info.base===API && info.fetches.some(x=>/127\.0\.0\.1:3002.*purchase-return/.test(x)) && !/真实 API 加载失败|Cannot GET/.test(info.text); add('P1-FE-'+p,ok,info)}
proc.kill('SIGTERM'); ev.summary={total:ev.checks.length,pass:ev.checks.filter(x=>x.status==='PASS').length,fail:ev.checks.filter(x=>x.status==='FAIL').length}; fs.writeFileSync(ROOT+'/采购模块P1采购退换货前端修复复验证据-20260720.json',JSON.stringify(ev,null,2)); console.log('EVIDENCE='+ROOT+'/采购模块P1采购退换货前端修复复验证据-20260720.json'); console.log(JSON.stringify(ev.summary)); if(ev.summary.fail)process.exitCode=2;})().catch(e=>{ev.fatal=String(e.stack||e);fs.writeFileSync(ROOT+'/采购模块P1采购退换货前端修复复验证据-20260720.json',JSON.stringify(ev,null,2));console.error(e);process.exit(1)})
